import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import {
  Users, CreditCard, Car, CheckCircle, AlertTriangle,
  RefreshCw, X
} from 'lucide-react';

const API_BASE = '/api/admin';

interface Driver {
  id: string;
  name: string | null;
  phone: string;
  vehicleType: string;
  kycStatus: string;
  createdAt: string;
}

interface KycResponse {
  drivers: Driver[];
  total: number;
  page: number;
  limit: number;
}

interface PaymentRecord {
  id: string;
  tripId: string;
  riderId: string;
  amount: number;
  status: string;
  createdAt: string;
}

interface TripReport {
  id: string;
  status: string;
  riderId: string;
  createdAt: string;
  estimatedFare: number | null;
  finalFare: number | null;
}

/* ---- Helpers ---- */
function StatusBadge({ status }: { status: string }) {
  const s = status?.toLowerCase() || '';
  const cls =
    s === 'pending' ? 'badge badge-pending' :
    s === 'approved' || s === 'completed' || s === 'success' ? 'badge badge-approved' :
    s === 'rejected' || s === 'failed' || s === 'cancelled' ? 'badge badge-rejected' :
    'badge badge-info';
  return <span className={cls}>{status}</span>;
}

function shortId(id: string) {
  return id?.length > 10 ? `…${id.slice(-8)}` : id;
}

/* ---- Rejection Modal ---- */
interface RejectModalProps {
  driverName: string;
  onConfirm: (reason: string) => void;
  onCancel: () => void;
}

function RejectModal({ driverName, onConfirm, onCancel }: RejectModalProps) {
  const [reason, setReason] = useState('');
  return (
    <div className="modal-overlay" role="dialog" aria-modal="true" aria-labelledby="modal-title" onClick={onCancel}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <h2 className="modal-title" id="modal-title">Reject KYC Application</h2>
        <p className="modal-desc">
          You are about to reject the KYC application for <strong>{driverName || 'this driver'}</strong>. Please provide a reason.
        </p>
        <textarea
          className="modal-textarea"
          placeholder="Enter rejection reason..."
          value={reason}
          onChange={e => setReason(e.target.value)}
          autoFocus
          aria-label="Rejection reason"
        />
        <div className="modal-actions">
          <button className="btn-secondary" onClick={onCancel}>Cancel</button>
          <button
            className="btn-reject"
            onClick={() => reason.trim() && onConfirm(reason.trim())}
            disabled={!reason.trim()}
            style={{ padding: '0.625rem 1.25rem', fontSize: '0.875rem' }}
          >
            Confirm Rejection
          </button>
        </div>
      </div>
    </div>
  );
}

/* ---- Main Dashboard ---- */
export default function Dashboard() {
  const [activeTab, setActiveTab] = useState<'kyc' | 'payments' | 'trips'>('kyc');
  const [kycData, setKycData] = useState<KycResponse | null>(null);
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [trips, setTrips] = useState<TripReport[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [rejectTarget, setRejectTarget] = useState<Driver | null>(null);

  const token = localStorage.getItem('adminToken') || '';
  const authHeader = { headers: { Authorization: `Bearer ${token}` } };

  const fetchKycData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get<KycResponse>(`${API_BASE}/kyc/pending`, authHeader);
      setKycData(res.data);
    } catch (err: any) {
      setError(err.response?.data?.message || err.message);
    }
    setLoading(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  const fetchPayments = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get<{ payments: PaymentRecord[] }>(`${API_BASE}/payments/search`, authHeader);
      setPayments(res.data.payments);
    } catch (err: any) {
      setError(err.response?.data?.message || err.message);
    }
    setLoading(false);
  };

  const fetchTrips = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get<{ trips: TripReport[] }>(`${API_BASE}/trips/reports`, authHeader);
      setTrips(res.data.trips);
    } catch (err: any) {
      setError(err.response?.data?.message || err.message);
    }
    setLoading(false);
  };

  const handleApprove = async (driverId: string) => {
    await axios.post(`${API_BASE}/kyc/${driverId}/approve`, {}, authHeader);
    fetchKycData();
  };

  const handleReject = async (driverId: string, reason: string) => {
    await axios.post(`${API_BASE}/kyc/${driverId}/reject`, { reason }, authHeader);
    setRejectTarget(null);
    fetchKycData();
  };

  useEffect(() => {
    fetchKycData();
  }, []);

  const switchTab = (tab: 'kyc' | 'payments' | 'trips') => {
    setActiveTab(tab);
    if (tab === 'kyc') fetchKycData();
    else if (tab === 'payments') fetchPayments();
    else fetchTrips();
  };

  /* Stats derived from data */
  const completedTrips = trips.filter(t => t.status?.toLowerCase() === 'completed').length;
  const totalRevenue = payments.reduce((sum, p) => sum + (p.amount || 0), 0);

  return (
    <>
      {rejectTarget && (
        <RejectModal
          driverName={rejectTarget.name || 'Unknown Driver'}
          onConfirm={reason => handleReject(rejectTarget.id, reason)}
          onCancel={() => setRejectTarget(null)}
        />
      )}

      <div className="dashboard">
        {/* Header */}
        <div className="dashboard-header">
          <div className="dashboard-title-row">
            <div>
              <h1 className="dashboard-title">Admin Dashboard</h1>
              <p className="dashboard-subtitle">
                Manage KYC approvals, payments, and trip reports
              </p>
            </div>
            <div className="header-actions">
              <button
                id="refresh-btn"
                className="btn-secondary"
                onClick={() => switchTab(activeTab)}
                disabled={loading}
                aria-label="Refresh current view"
              >
                <RefreshCw size={16} />
                Refresh
              </button>
            </div>
          </div>

          {/* Stats cards */}
          <div className="stats-grid">
            <div className="stat-card">
              <div className="stat-icon brand" aria-hidden="true"><Users size={20} /></div>
              <div className="stat-value">{kycData?.total ?? '—'}</div>
              <div className="stat-label">Pending KYC</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon success" aria-hidden="true"><CreditCard size={20} /></div>
              <div className="stat-value">
                {payments.length > 0 ? `₹${totalRevenue.toLocaleString('en-IN')}` : '—'}
              </div>
              <div className="stat-label">Total Payments</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon warning" aria-hidden="true"><Car size={20} /></div>
              <div className="stat-value">{trips.length > 0 ? trips.length : '—'}</div>
              <div className="stat-label">Total Trips</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon info" aria-hidden="true"><CheckCircle size={20} /></div>
              <div className="stat-value">{trips.length > 0 ? completedTrips : '—'}</div>
              <div className="stat-label">Completed Trips</div>
            </div>
          </div>

          {/* Tabs */}
          <div className="dashboard-tabs" role="tablist" aria-label="Dashboard sections">
            <button
              id="tab-kyc"
              role="tab"
              aria-selected={activeTab === 'kyc'}
              className={`tab ${activeTab === 'kyc' ? 'active' : ''}`}
              onClick={() => switchTab('kyc')}
            >
              <Users size={16} />
              KYC Management
              {kycData?.total !== undefined && kycData.total > 0 && (
                <span className="tab-count" aria-label={`${kycData.total} pending`}>
                  {kycData.total}
                </span>
              )}
            </button>
            <button
              id="tab-payments"
              role="tab"
              aria-selected={activeTab === 'payments'}
              className={`tab ${activeTab === 'payments' ? 'active' : ''}`}
              onClick={() => switchTab('payments')}
            >
              <CreditCard size={16} />
              Payments
            </button>
            <button
              id="tab-trips"
              role="tab"
              aria-selected={activeTab === 'trips'}
              className={`tab ${activeTab === 'trips' ? 'active' : ''}`}
              onClick={() => switchTab('trips')}
            >
              <Car size={16} />
              Trip Reports
            </button>
          </div>
        </div>

        {/* Alerts */}
        {error && (
          <div className="error-state" role="alert">
            <AlertTriangle size={16} style={{ flexShrink: 0 }} />
            <strong>Error:</strong>&nbsp;{error}
          </div>
        )}

        {/* ---- KYC Tab ---- */}
        {activeTab === 'kyc' && (
          <div className="tab-content" role="tabpanel" aria-labelledby="tab-kyc">
            <div className="tab-content-header">
              <div>
                <h2 className="tab-content-title">Pending KYC Approvals</h2>
                {kycData?.total !== undefined && (
                  <span className="tab-content-count">{kycData.total} application{kycData.total !== 1 ? 's' : ''} awaiting review</span>
                )}
              </div>
            </div>

            {loading ? (
              <div className="loading-state" aria-live="polite" aria-busy="true">
                <div className="loading-spinner" aria-hidden="true" />
                Loading KYC applications…
              </div>
            ) : kycData?.drivers && kycData.drivers.length > 0 ? (
              <div className="data-table-wrapper">
                <table className="data-table" aria-label="KYC applications">
                  <thead>
                    <tr>
                      <th scope="col">Driver</th>
                      <th scope="col">Phone</th>
                      <th scope="col">Vehicle</th>
                      <th scope="col">Status</th>
                      <th scope="col">Applied</th>
                      <th scope="col">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {kycData.drivers.map(driver => (
                      <tr key={driver.id}>
                        <td className="cell-primary">{driver.name || 'Unknown'}</td>
                        <td>{driver.phone}</td>
                        <td>
                          <span className="vehicle-chip">{driver.vehicleType}</span>
                        </td>
                        <td><StatusBadge status={driver.kycStatus} /></td>
                        <td className="cell-mono">
                          {new Date(driver.createdAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                        </td>
                        <td>
                          <div className="action-group">
                            <button
                              id={`approve-${driver.id}`}
                              className="btn-approve"
                              onClick={() => handleApprove(driver.id)}
                              aria-label={`Approve KYC for ${driver.name || 'driver'}`}
                            >
                              ✓ Approve
                            </button>
                            <button
                              id={`reject-${driver.id}`}
                              className="btn-reject"
                              onClick={() => setRejectTarget(driver)}
                              aria-label={`Reject KYC for ${driver.name || 'driver'}`}
                            >
                              ✕ Reject
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="empty-state">
                <span className="empty-state-icon" aria-hidden="true"><CheckCircle size={32} /></span>
                <p className="empty-state-title">All caught up!</p>
                <p className="empty-state-desc">No pending KYC applications at the moment.</p>
              </div>
            )}
          </div>
        )}

        {/* ---- Payments Tab ---- */}
        {activeTab === 'payments' && (
          <div className="tab-content" role="tabpanel" aria-labelledby="tab-payments">
            <div className="tab-content-header">
              <div>
                <h2 className="tab-content-title">Payment History</h2>
                {payments.length > 0 && (
                  <span className="tab-content-count">{payments.length} transaction{payments.length !== 1 ? 's' : ''}</span>
                )}
              </div>
            </div>

            {loading ? (
              <div className="loading-state" aria-live="polite" aria-busy="true">
                <div className="loading-spinner" aria-hidden="true" />
                Loading payment records…
              </div>
            ) : payments.length > 0 ? (
              <div className="data-table-wrapper">
                <table className="data-table" aria-label="Payment history">
                  <thead>
                    <tr>
                      <th scope="col">Payment ID</th>
                      <th scope="col">Trip ID</th>
                      <th scope="col">Rider</th>
                      <th scope="col">Amount</th>
                      <th scope="col">Status</th>
                      <th scope="col">Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {payments.map(payment => (
                      <tr key={payment.id}>
                        <td className="cell-mono">{shortId(payment.id)}</td>
                        <td className="cell-mono">{shortId(payment.tripId)}</td>
                        <td className="cell-mono">{shortId(payment.riderId)}</td>
                        <td className="cell-amount">₹{payment.amount.toLocaleString('en-IN')}</td>
                        <td><StatusBadge status={payment.status} /></td>
                        <td className="cell-mono">
                          {new Date(payment.createdAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="empty-state">
                <span className="empty-state-icon" aria-hidden="true"><CreditCard size={32} /></span>
                <p className="empty-state-title">No payments found</p>
                <p className="empty-state-desc">Payment records will appear here once transactions are made.</p>
              </div>
            )}
          </div>
        )}

        {/* ---- Trips Tab ---- */}
        {activeTab === 'trips' && (
          <div className="tab-content" role="tabpanel" aria-labelledby="tab-trips">
            <div className="tab-content-header">
              <div>
                <h2 className="tab-content-title">Trip Reports</h2>
                {trips.length > 0 && (
                  <span className="tab-content-count">{trips.length} trip{trips.length !== 1 ? 's' : ''} recorded</span>
                )}
              </div>
            </div>

            {loading ? (
              <div className="loading-state" aria-live="polite" aria-busy="true">
                <div className="loading-spinner" aria-hidden="true" />
                Loading trip reports…
              </div>
            ) : trips.length > 0 ? (
              <div className="data-table-wrapper">
                <table className="data-table" aria-label="Trip reports">
                  <thead>
                    <tr>
                      <th scope="col">Trip ID</th>
                      <th scope="col">Status</th>
                      <th scope="col">Rider</th>
                      <th scope="col">Est. Fare</th>
                      <th scope="col">Final Fare</th>
                      <th scope="col">Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {trips.map(trip => (
                      <tr key={trip.id}>
                        <td className="cell-mono">{shortId(trip.id)}</td>
                        <td><StatusBadge status={trip.status} /></td>
                        <td className="cell-mono">{shortId(trip.riderId)}</td>
                        <td>{trip.estimatedFare != null ? <span className="cell-amount">₹{trip.estimatedFare.toLocaleString('en-IN')}</span> : <span style={{ color: 'var(--text-muted)' }}>—</span>}</td>
                        <td>{trip.finalFare != null ? <span className="cell-amount">₹{trip.finalFare.toLocaleString('en-IN')}</span> : <span style={{ color: 'var(--text-muted)' }}>—</span>}</td>
                        <td className="cell-mono">
                          {new Date(trip.createdAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="empty-state">
                <span className="empty-state-icon" aria-hidden="true"><Car size={32} /></span>
                <p className="empty-state-title">No trips found</p>
                <p className="empty-state-desc">Trip reports will appear here once rides are completed.</p>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
}
